mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  float r = length(p);
  float a = atan(p.y, p.x);
  float tear = abs(p.x + sin(p.y * 10.0 + time * 5.0) * 0.08) - 0.03;
  float arcs = abs(sin(r * 20.0 - time * 8.0 + a * 3.0)) - 0.1;
  vec3 col = vec3(0.01, 0.03, 0.08);
  col += vec3(0.1, 0.7, 1.2) * (0.02 / (0.02 + abs(tear)));
  col += vec3(0.8, 0.2, 1.0) * (0.01 / (0.02 + abs(arcs))) * smoothstep(1.5, 0.0, r);
  col *= (1.0 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
